// La respuesta del formulario tiene que decir algo cierto y corto.
// El informe HTML completo queda en la salida del nodo anterior,
// visible en la ejecucion.
const entrada = $('Form Trigger — Formulario').first().json;
const txn = entrada['Transaction ID'] || 'la transaccion';
const respuesta = $input.first().json;
const html = respuesta.data || respuesta.body || '';

return [{
  json: {
    resultado: html
      ? `Investigacion completada para ${txn}. El informe quedo en la ejecucion de este workflow.`
      : `No se pudo completar la investigacion de ${txn}. Revisa la ejecucion para ver el error.`,
  },
}];

// Un formulario lo completa una persona: el identificador puede venir
// con cualquier cosa. Se corta antes de gastar una llamada a la API.
const txn = ($('Form Trigger — Formulario').first().json['Transaction ID'] || '').trim();

return [{
  json: {
    resultado: `«${txn}» no tiene el formato esperado. `
      + `El identificador es TXN- seguido de cinco digitos, por ejemplo TXN-00051.`,
  },
}];

// La API puede estar dormida, caida, o el caso puede no existir.
// El formulario tiene que decir que paso, no quedarse en blanco.
// El error se lee del nodo que fallo: el de la alerta ya paso por el medio.
const txn = ($('Form Trigger — Formulario').first().json['Transaction ID'] || 'la transaccion').trim();
const error = $('Analizar el Caso').first().json.error || {};
const detalle = error.message || error.description || 'la API no respondio';

return [{
  json: {
    resultado: `No se pudo completar la investigacion de ${txn}: ${detalle}. `
      + `Quedo registrada como alerta y el detalle esta en la ejecucion de este workflow.`,
  },
}];
